begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('99000000-0000-4000-8000-000000000001','links@example.test','{}'),('99000000-0000-4000-8000-000000000002','other-links@example.test','{}');
insert into user_roles(user_id,role) values('99000000-0000-4000-8000-000000000001','ADMIN');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated,service_role;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated,service_role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Link','Family','+13035550404','link@example.test','SMS',null,null);
insert into fx select 'other',id from save_client(auth.uid(),null,null,'Other','Family','+13035550405','other@example.test','SMS',null,null);
insert into fx select 'product',id from save_catalog_product(null,null,'Synthetic exam','service','','visit',1000,true);
select create_billing_invoice('99100000-0000-4000-8000-000000000001',(select id from fx where k='client'));
select add_invoice_service('99100000-0000-4000-8000-000000000002','99100000-0000-4000-8000-000000000001',null,(select id from fx where k='product'),1);
select throws_ok($$select preview_document_link('invoice','99100000-0000-4000-8000-000000000001',(select id from fx where k='client'))$$,'42501',null,'Consent missing blocks invoice preview');
select record_sms_consent(auth.uid(),(select id from fx where k='client'),'+13035550404',true,'WRITTEN','SYNTHETIC ONLY',null);
