select is((select v->>'recipient' from data where k='invoice'),'+13035550404','Invoice uses phone without email coercion');
select ok(not (select v ? 'bundle' from data where k='invoice'),'Staff preview omits private bundle');
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Link dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
select prepare_patient_document('99100000-0000-4000-8000-000000000010',(select id from fx where k='pet'),null,'original.pdf','application/pdf',9,'medical_record','Synthetic source',null,'client_shareable');
insert into storage.objects(bucket_id,name,metadata) select 'patient-documents',file_path,'{"size":9,"mimetype":"application/pdf"}' from patient_documents where id='99100000-0000-4000-8000-000000000010';
select finalize_patient_document('99100000-0000-4000-8000-000000000010');
insert into data values('selection','{"document_ids":["99100000-0000-4000-8000-000000000010"]}');
insert into data values('record_preview',preview_record_release((select id from fx where k='pet'),(select id from fx where k='client'),'SMS','+13035550404',(select v from data where k='selection')));
reset role;
insert into record_release_policy(id,enabled,accepted_by,accepted_at,acceptance_reference,accepted_schema_version) values(true,true,'Synthetic reviewer',now(),'SYNTHETIC ONLY',4) on conflict(id) do update set enabled=true,accepted_at=now(),accepted_schema_version=4;
insert into conversations(id,client_id) values('99100000-0000-4000-8000-000000000003',(select id from fx where k='client')),('99100000-0000-4000-8000-000000000004',(select id from fx where k='other'));
set local role authenticated;
select confirm_record_release('99100000-0000-4000-8000-000000000011',(select id from fx where k='pet'),(select id from fx where k='client'),'SMS','+13035550404',(select v from data where k='selection'),(select v->'snapshot' from data where k='record_preview'),(select v->>'source_hash' from data where k='record_preview'),true);
insert into data values('email_preview',preview_record_release((select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','link@example.test',(select v from data where k='selection')));
select confirm_record_release('99100000-0000-4000-8000-000000000012',(select id from fx where k='pet'),(select id from fx where k='client'),'EMAIL','link@example.test',(select v from data where k='selection'),(select v->'snapshot' from data where k='email_preview'),(select v->>'source_hash' from data where k='email_preview'),true);
select throws_ok($$select preview_document_link('record_release','99100000-0000-4000-8000-000000000012',(select id from fx where k='client'))$$,'42501',null,'EMAIL release cannot be coerced into SMS grant');
select throws_ok($$select preview_document_link('invoice','99100000-0000-4000-8000-000000000001',(select id from fx where k='other'))$$,'42501',null,'Wrong source household denied');
insert into data values('record_release',preview_document_link('record_release','99100000-0000-4000-8000-000000000011',(select id from fx where k='client')));
create function pg_temp.prepare_link(p_id uuid,p_family text) returns jsonb language sql as $$select prepare_document_link(p_id,p_family,case when p_family='invoice' then '99100000-0000-4000-8000-000000000001'::uuid else '99100000-0000-4000-8000-000000000011'::uuid end,(select id from fx where k='client'),'99100000-0000-4000-8000-000000000003','+13035550404',(select v->>'source_hash' from data where k=p_family),now()+interval '1 day','Reviewed documents: {{document_link}}','https://thelivingroom.vet','test-v1')$$;
select lives_ok($$select pg_temp.prepare_link('99200000-0000-4000-8000-000000000001','invoice')$$,'Immutable invoice grant prepared');
select lives_ok($$select pg_temp.prepare_link('99200000-0000-4000-8000-000000000001','invoice')$$,'Exact invoice retry resolves');
select lives_ok($$select pg_temp.prepare_link('99200000-0000-4000-8000-000000000002','record_release')$$,'SMS record grant prepared');
select throws_ok($$select pg_temp.prepare_link(gen_random_uuid(),'invoice')$$,'23505',null,'Competing unresolved invoice request denied');
select is(recover_document_link('invoice','99100000-0000-4000-8000-000000000001')#>>'{grant,id}','99200000-0000-4000-8000-000000000001','Lost request recovered');
select throws_ok($$select prepare_document_link('99200000-0000-4000-8000-000000000001','invoice','99100000-0000-4000-8000-000000000001',(select id from fx where k='client'),'99100000-0000-4000-8000-000000000003','+13035550404',(select v->>'source_hash' from data where k='invoice'),now()+interval '2 days','Reviewed documents: {{document_link}}','https://thelivingroom.vet','test-v1')$$,'23505',null,'Retry never extends expiry');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001',auth.uid(),'{}',repeat('a',64),repeat('b',64))$$,'42501',null,'Staff cannot fabricate captured bytes');
select throws_ok($$select * from document_link_payloads$$,'42501',null,'Staff cannot directly read payload table');
select throws_ok($$select document_link_source('invoice',null,null)$$,'42501',null,'Private source validator denied to staff');
insert into data values('invoice_payload',jsonb_build_object('artifacts',jsonb_build_array(jsonb_build_object('filename','invoice.html','mime_type','text/html','document_id',null,'content',encode(convert_to('<h1>Synthetic invoice</h1>','UTF8'),'base64')))));
insert into data values('record_payload',jsonb_build_object('artifacts',jsonb_build_array(jsonb_build_object('filename','record.html','mime_type','text/html','document_id',null,'content',encode(convert_to('<h1>Synthetic record</h1>','UTF8'),'base64')),jsonb_build_object('filename','original.pdf','mime_type','application/pdf','document_id','99100000-0000-4000-8000-000000000010','content','JVBERi10ZXN0'))));
reset role;set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000002',(select v::text from data where k='invoice_payload'),repeat('a',64),repeat('b',64))$$,'42501',null,'Capture actor must match');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001','{}',repeat('a',64),repeat('b',64))$$,'23514',null,'Missing artifacts rejected');
select lives_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001',(select v::text from data where k='invoice_payload'),repeat('a',64),repeat('b',64))$$,'Invoice captured');
select lives_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001',(select v::text from data where k='invoice_payload'),repeat('a',64),repeat('b',64))$$,'Exact capture retry resolves');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000001','99000000-0000-4000-8000-000000000001',(select v::text from data where k='invoice_payload'),repeat('c',64),repeat('b',64))$$,'23505',null,'Token hash cannot be replaced');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000001',(select jsonb_set(v,'{artifacts,1,content}','"YmFk"')::text from data where k='record_payload'),repeat('a',64),repeat('b',64))$$,'23514',null,'Corrupt original size/signature denied');
select throws_ok($$select capture_document_link('99200000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000001',(select jsonb_set(v,'{artifacts,1,document_id}','"99100000-0000-4000-8000-000000000099"')::text from data where k='record_payload'),repeat('a',64),repeat('b',64))$$,'23514',null,'Unselected original denied');
select lives_ok($$select capture_document_link('99200000-0000-4000-8000-000000000002','99000000-0000-4000-8000-000000000001',(select v::text from data where k='record_payload'),repeat('a',64),repeat('b',64))$$,'Selected record originals captured');
select throws_ok($$select retrieve_document_link('99200000-0000-4000-8000-000000000001',repeat('a',64),null)$$,'42501',null,'Captured but unreviewed grant cannot retrieve');
reset role;set local role authenticated;select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(read_document_link_artifact('99200000-0000-4000-8000-000000000002',1)->>'content',encode(convert_to('%PDF-test','UTF8'),'base64'),'Actor reviews exact original before public activation');
select throws_ok($$select read_document_link_artifact('99200000-0000-4000-8000-000000000002',null)$$,'42501',null,'Staff artifact index required');
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select read_document_link_artifact('99200000-0000-4000-8000-000000000002',1)$$,'42501',null,'Other actor cannot inspect frozen originals');
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into data values('invoice_ready',recover_document_link('invoice','99100000-0000-4000-8000-000000000001'));
insert into data values('record_ready',recover_document_link('record_release','99100000-0000-4000-8000-000000000011'));
select throws_ok($$select attest_document_link('99200000-0000-4000-8000-000000000001',repeat('f',64),repeat('b',64),true)$$,'42501',null,'Wrong reviewed hash denied');
select throws_ok($$select attest_document_link('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),false)$$,'42501',null,'Explicit attestation required');
select throws_ok($$select enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),true)$$,'42501',null,'Captured but unreviewed link cannot queue');
select lives_ok($$select attest_document_link('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),true)$$,'Invoice exact review activates retrieval');
select lives_ok($$select attest_document_link('99200000-0000-4000-8000-000000000002',(select v->>'artifact_hash' from data where k='record_ready'),repeat('b',64),true)$$,'Record exact review activates retrieval');
select throws_ok($$select enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',repeat('f',64),repeat('b',64),true)$$,'42501',null,'Queue requires exact artifact review');
select throws_ok($$select enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),false)$$,'42501',null,'Queue requires explicit attestation');
insert into data values('invoice_queue',to_jsonb(enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),true)));
insert into data values('record_queue',to_jsonb(enqueue_document_link_sms('99200000-0000-4000-8000-000000000002',(select v->>'artifact_hash' from data where k='record_ready'),repeat('b',64),true)));
select is((select v->>'body' from data where k='invoice_queue'),'Reviewed documents: {{document_link}}','Invoice outbox only stores template');
select is((select v->>'body' from data where k='record_queue'),'Reviewed documents: {{document_link}}','Record outbox only stores template');
select is(recover_document_link('invoice','99100000-0000-4000-8000-000000000001')#>>'{receipt,outbox_id}',(select v->>'id' from data where k='invoice_queue'),'Lost enqueue response recovered');
select is((enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),true)).id::text,(select v->>'id' from data where k='invoice_queue'),'Exact queue retry has one outbox');
select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),true)$$,'42501',null,'Other actor cannot replay queue');
reset role;
select is((select count(*)::integer from messages where conversation_id='99100000-0000-4000-8000-000000000003'),2,'Each grant produces exactly one history entry');
select throws_ok($$update messages set content='https://thelivingroom.vet/shared/11223344-1234-4234-8234-123456789abc#v1.'||repeat('a',43) where id=(select (v->>'message_id')::uuid from data where k='invoice_queue')$$,'23514',null,'Literal capability rejected from message history');
select throws_ok($$update document_link_grants set message_template='{{document_link}} v1.'||repeat('a',43) where id='99200000-0000-4000-8000-000000000001'$$,'23514',null,'Literal capability cannot be embedded in template');
select throws_ok($$delete from document_link_outbox_links$$,'23514',null,'Queue association immutable');
-- Synthetic direct lease setup isolates each final-boundary test from unrelated pending rows.
update communication_outbox set state='claimed',lease_token=gen_random_uuid(),lease_expires_at=now()+interval '2 minutes' where id in(select (v->>'id')::uuid from data where k in ('invoice_queue','record_queue'));
insert into data values('invoice_lease',(select to_jsonb(o) from communication_outbox o where id=(select (v->>'id')::uuid from data where k='invoice_queue'))),('record_lease',(select to_jsonb(o) from communication_outbox o where id=(select (v->>'id')::uuid from data where k='record_queue')));
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(document_link_delivery_context((select (v->>'id')::uuid from data where k='invoice_lease'),(select (v->>'lease_token')::uuid from data where k='invoice_lease'))->>'message_hash',repeat('b',64),'Worker receives message digest and immutable context');
select throws_ok($$select document_link_delivery_context((select (v->>'id')::uuid from data where k='invoice_lease'),gen_random_uuid())$$,'40001',null,'Worker needs current exact lease');
select is((start_communication_attempt((select (v->>'id')::uuid from data where k='invoice_lease'),(select (v->>'lease_token')::uuid from data where k='invoice_lease'),'{"from":"+13035550199","account_sid":"ACaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}')).state,'failed','Old worker lacking proof fails closed');
reset role;
select is((select count(*)::integer from communication_attempts where outbox_id=(select (v->>'id')::uuid from data where k='invoice_queue')),0,'Old worker cannot begin provider attempt');
-- Source changes after worker context read are checked again by final guard.
create function pg_temp.changed_source_attempt(p_case text) returns text language plpgsql as $$declare result text;begin
 begin
  if p_case='phone' then update clients set primary_phone='+13035550999' where id=(select id from fx where k='client');
  elsif p_case='consent' then update sms_consent set opted_in=false where client_id=(select id from fx where k='client');
  elsif p_case='policy' then update record_release_policy set accepted_schema_version=1;
  elsif p_case='actor' then update profiles set is_active=false where id='99000000-0000-4000-8000-000000000001';
  elsif p_case='withdrawn' then insert into record_release_events(id,release_id,kind,reason,created_by) values(gen_random_uuid(),'99100000-0000-4000-8000-000000000011','withdrawn','Synthetic withdrawal','99000000-0000-4000-8000-000000000001');
  end if;
select (start_communication_attempt((select (v->>'id')::uuid from data where k='record_lease'),(select (v->>'lease_token')::uuid from data where k='record_lease'),jsonb_build_object('from','+13035550199','account_sid','ACaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','document_link_token_hash',repeat('a',64),'document_link_message_hash',repeat('b',64),'document_link_artifact_hash',(select v->>'artifact_hash' from data where k='record_ready')))).state into result;
  raise exception 'rollback synthetic change';
 exception when raise_exception then return result;end;
end $$;
select is(pg_temp.changed_source_attempt('phone'),'failed','Changed phone rejected at final guard');
select is(pg_temp.changed_source_attempt('consent'),'failed','Withdrawn SMS consent rejected at final guard');
select is(pg_temp.changed_source_attempt('policy'),'failed','Clinical schema no longer accepted at final guard');
select is(pg_temp.changed_source_attempt('actor'),'failed','Inactive preparing actor rejected at final guard');
select is(pg_temp.changed_source_attempt('withdrawn'),'failed','Withdrawn medical release rejected at final guard');
set local role service_role;
select is((start_communication_attempt((select (v->>'id')::uuid from data where k='record_lease'),(select (v->>'lease_token')::uuid from data where k='record_lease'),jsonb_build_object('from','+13035550199','account_sid','ACaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','document_link_token_hash',repeat('a',64),'document_link_message_hash',repeat('b',64),'document_link_artifact_hash',(select v->>'artifact_hash' from data where k='record_ready')))).state,'claimed','Exact materialization proof permits record provider attempt');
reset role;
select is((select provider_config from communication_outbox where id=(select (v->>'id')::uuid from data where k='record_queue')),'{"from":"+13035550199","account_sid":"ACaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}'::jsonb,'Persistent provider metadata only has sender information');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"99000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select revoke_document_link('99200000-0000-4000-8000-000000000001','Synthetic revoked after queue');
select is((enqueue_document_link_sms('99200000-0000-4000-8000-000000000001',(select v->>'artifact_hash' from data where k='invoice_ready'),repeat('b',64),true)).id::text,(select v->>'id' from data where k='invoice_queue'),'Committed queue receipt survives later revocation');
select is(recover_document_link('invoice','99100000-0000-4000-8000-000000000001')#>>'{receipt,state}','failed','Recovery reports old-worker rejection without resending');
select * from finish();
rollback;
